def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == 0:
        return d1
    diff = {}
    for k, v in d1.items():
        if k not in d2:
            diff[k] = v
        elif isinstance(v, dict):
            diff[k] = difference(v, d2[k], level - 1)
        elif v != d2[k]:
            diff[k] = v
    return diff

def _get_resource_name_regex():
    """Build or return the regular expressions that are used to validate
    the name of the Krake resources.

    Returns:
        (re.Pattern): the compiled regular expressions, to validate
        the resource name.
    """
    if not hasattr(resource, '_meta'):
        raise ValueError("Resource class has no _meta attribute")
    if not hasattr(resource._meta, 'name_regex'):
        raise ValueError("Resource class has no name_regex attribute")
    if not isinstance(resource._meta.name_regex, str):
        raise ValueError("Resource class name_regex attribute is not a string")
    if not resource._meta.name_regex:
        raise ValueError("Resource class name_regex attribute is empty")
    try:
        return re.compile(resource._meta.name_regex)
    except re.error as e:
        raise ValueError("Resource class name_regex attribute is not a valid regular expression") from e
